var update = flag.Bool("update", false, "rewrite docs/evals/offline.md and offline.json")

const offlineHeader = "# Code Mode evals: scripted harness check (not evidence)\n\n" +
	"Generated by `go test ./evals -run TestOfflineRun -update`. The model is scripted: it makes the\n" +
	"same calls in every arm, and its token counts are estimates from request size. These numbers check\n" +
	"that the harness, the engine and the trace records fit together; they are not evidence about Code\n" +
	"Mode or any model. See code-mode.md.\n\n"

// TestOfflineRun runs every scenario in every arm against its scripted model,
// with the real engine and tools, and checks the harness end to end: the
// graders pass, the metrics come out of the trace records, and the report is
// the checked-in docs/evals/offline report. The environment's default model
// must not change it.
func TestOfflineRun(t *testing.T) {
	t.Setenv("NANITE_DEFAULT_MODEL", "some-other-model")
	rep, err := Run(context.Background(), Config{TurnTokens: 500000}, Scenarios())
	if err != nil {
		t.Fatal(err)
	}
	want := 0
	for _, s := range Scenarios() {
		want += len(s.AllArms())
	}
	if len(rep.Results) != want || rep.Model != ScriptedModel || rep.SpentUSD <= 0 {
		t.Fatalf("report: %d results (want %d), model %q, spent %v", len(rep.Results), want, rep.Model, rep.SpentUSD)
	}
	by := map[string]Result{}
	for _, r := range rep.Results {
		by[r.Scenario+"/"+r.Arm] = r
		if !r.Success {
			t.Errorf("%s/%s failed: %s", r.Scenario, r.Arm, r.Why)
		}
		if r.ParentContextTokens == 0 || r.TotalTokens < r.ParentContextTokens || r.CostUSD <= 0 {
			t.Errorf("%s/%s: metrics missing: %+v", r.Scenario, r.Arm, r)
		}
		if r.Mode == Direct && (r.Subtasks != 0 || len(r.Variants) != 0) {
			t.Errorf("%s/direct started subtasks: %+v", r.Scenario, r)
		}
	}
	// What each scripted subtask run does, as the trace records report it.
	for name, want := range map[string]struct {
		subtasks int
		variants string
	}{
		"code-search/subtask": {1, "research"}, "research/subtask": {1, "research"}, "chore/subtask": {1, "worker"},
		"council/subtask": {4, "council,reviewer"}, "history/subtask": {1, "scribe"}, "history/subtask last_n=1": {1, "scribe"},
		"history/subtask last_n=20": {1, "scribe"}, "inventory/subtask": {1, "research"}, "inventory/subtask result_cap=1500": {1, "research"},
	} {
		r := by[name]
		if r.Subtasks != want.subtasks || strings.Join(r.Variants, ",") != want.variants {
			t.Errorf("%s: %d subtasks running %v, want %d running %s", name, r.Subtasks, r.Variants, want.subtasks, want.variants)
		}
	}
	// Six writes ask for approval in both modes; a subtask's asks are relayed
	// to the root's gate.
	for _, arm := range []string{"direct", "subtask"} {
		if got := by["chore/"+arm].Approvals; got != 6 {
			t.Errorf("chore/%s: %d approvals, want 6", arm, got)
		}
	}
	// Over the small cap the parent fetches the stored result; under the
	// default cap it does not.
	if got := by["inventory/subtask result_cap=1500"].ParentToolCalls; got != 2 {
		t.Errorf("inventory, small cap: %d parent tool calls, want 2 (subtask, fetch)", got)
	}
	if got := by["inventory/subtask"].ParentToolCalls; got != 1 {
		t.Errorf("inventory, default cap: %d parent tool calls, want 1", got)
	}
	// A larger last_n starts the subtask with more of the conversation.
	if a, b := by["history/subtask last_n=1"].TotalTokens, by["history/subtask last_n=20"].TotalTokens; a >= b {
		t.Errorf("history: last_n=1 used %d tokens, last_n=20 %d; want fewer", a, b)
	}

	md := offlineHeader + Markdown(rep, false)
	if strings.Contains(md, "% of the direct") {
		t.Error("a scripted report makes ratio claims")
	}
	js, err := JSON(rep, false)
	if err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join("..", "docs", "evals")
	if *update {
		if err := os.MkdirAll(dir, 0o750); err != nil {
			t.Fatal(err)
		}
		for name, data := range map[string][]byte{"offline.md": []byte(md), "offline.json": js} {
			if err := os.WriteFile(filepath.Join(dir, name), data, 0o644); err != nil { //nolint:gosec // checked-in docs are world-readable
				t.Fatal(err)
			}
		}
	}
	for name, got := range map[string]string{"offline.md": md, "offline.json": string(js)} {
		want, err := os.ReadFile(filepath.Join(dir, name)) //nolint:gosec // fixed file names under docs/evals
		if err != nil {
			t.Fatalf("%v (run with -update to create it)", err)
		}
		if string(want) != got {
			t.Errorf("docs/evals/%s is out of date; run go test ./evals -run TestOfflineRun -update\n%s", name, got)
		}
	}
}

// TestDollarCapStopsTheRun: a request that would pass the cap is refused, the
// run in progress ends, the rest are skipped, and the report says so.
func TestDollarCapStopsTheRun(t *testing.T) {
	rep, err := Run(context.Background(), Config{MaxUSD: 2}, Scenarios())
	if err != nil {
		t.Fatal(err)
	}
	skipped, capped := 0, 0
	for _, r := range rep.Results {
		if r.Skipped != "" {
			skipped++
		}
		if strings.Contains(r.Why, "dollar cap") {
			capped++
		}
	}
	if skipped == 0 || capped != 1 || !strings.Contains(rep.Stopped, "dollar cap") {
		t.Fatalf("want one run stopped by the cap and later ones skipped; got %d capped, %d skipped, stopped %q", capped, skipped, rep.Stopped)
	}
	if rep.SpentUSD > 2 {
		t.Fatalf("spent $%.4f past the $2 cap", rep.SpentUSD)
	}
}

// TestInterruptedRunKeepsWhatRan: a cancelled context skips the runs not yet
// started, and the report keeps the spend so far.
func TestInterruptedRunKeepsWhatRan(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	rep, err := Run(ctx, Config{}, Scenarios()[:1])
	if err != nil {
		t.Fatal(err)
	}
	if len(rep.Results) != 2 || rep.Results[0].Skipped != "interrupted" || rep.Stopped != "interrupted" {
		t.Fatalf("report: %+v", rep)
	}
}

func TestMeterReservesTheWorstCase(t *testing.T) {
	m := &meter{price: Price{Input: 1, Output: 1}, max: 1}
	hold := 0.5
	for i := range 2 {
		if !m.reserve(hold) {
			t.Fatalf("half-dollar reservation %d refused under a dollar cap", i+1)
		}
	}
	if m.reserve(0.01) {
		t.Fatal("a third request was let past the reserved cap")
	}
	m.settle(hold, 0.1)
	if m.spentUSD() != 0.1 || m.over() != true {
		t.Fatalf("spent %v, over %v", m.spentUSD(), m.over())
	}
}

type completer struct{ fakeProvider }

func (completer) Complete(context.Context, llmtypes.ChatRequest) (string, error) {
	return strings.Repeat("x", 4000), nil
}

// fakeProvider satisfies the provider interface for tests that only call
// Complete.
type fakeProvider struct{ *scripted }

func TestCompleteIsMetered(t *testing.T) {
	m := &meter{price: Price{Input: 1, Output: 1}, max: 1}
	cancelled := false
	p := &metered{Provider: completer{fakeProvider{newScripted(Script{})}}, meter: m, cancel: func() { cancelled = true }}
	req := llmtypes.ChatRequest{SystemPrompt: strings.Repeat("y", 4000), MaxTokens: 100}
	if _, err := p.Complete(context.Background(), req); err != nil {
		t.Fatal(err)
	}
	// About 1000 tokens in, and 1001 out for the 4000-character answer, at $1/M.
	if got, want := m.spentUSD(), float64(requestTokens(req, nil)+1001)/1e6; math.Abs(got-want) > 1e-12 {
		t.Fatalf("Complete charged $%v", got)
	}
	m.max = m.spentUSD()
	if _, err := p.Complete(context.Background(), llmtypes.ChatRequest{MaxTokens: 100}); !errors.Is(err, errCapped) || !cancelled {
		t.Fatalf("over the cap: %v, cancelled %v", err, cancelled)
	}
}

// TestSubtaskArmWithoutTheRequiredVariantIsInvalid: a council run that never
// started the council variant did not test what it was meant to.
func TestSubtaskArmWithoutTheRequiredVariantIsInvalid(t *testing.T) {
	s := council()
	direct := s.Script
	s.Script = func(arm Arm) Script { return direct(Arm{Mode: Direct}) }
	s.Arms = nil
	rep, err := Run(context.Background(), Config{Modes: []Mode{Subtask}}, []Scenario{s})
	if err != nil {
		t.Fatal(err)
	}
	r := rep.Results[0]
	if r.Success || !r.Invalid || !strings.Contains(r.Why, "council variant did not run") {
		t.Fatalf("result: %+v", r)
	}
}

func TestGraders(t *testing.T) {
	ch := chore()
	ws := t.TempDir()
	if err := ch.install(ws); err != nil {
		t.Fatal(err)
	}
	for _, n := range choreNotes {
		p := filepath.Join(ws, "notes", n+".md")
		if err := os.WriteFile(p, []byte(strings.TrimRight(ch.read("notes/"+n+".md"), "\n")+"\n"+reviewedLine+"\n"), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	for answer, want := range map[string]bool{
		"Done.\nANSWER: Reviewed: 2026-11-20": false, // the date's 6 is not a count
		"Changed them.\nANSWER: 6":            true,
		"ANSWER: six files":                   true,
		"ANSWER: 16":                          false,
		"Changed 6 files.":                    false, // no ANSWER line
	} {
		if ok, why := ch.Grade(answer, ws); ok != want {
			t.Errorf("chore %q: %v (%s), want %v", answer, ok, why, want)
		}
	}
	cs := codeSearch()
	good := "ANSWER: src/config.go:loadMode, src/server.go:startServer; modes: dev, prod, test"
	for answer, want := range map[string]bool{
		good: true,
		"describeMode only mentions APP_MODE, so it is not one.\n" + good: true, // a decoy ruled out outside the line
		good + ", describeMode":                           false, // a decoy on the line
		strings.ReplaceAll(good, "loadMode", "loadModes"): false, // whole words only
	} {
		if ok, why := cs.Grade(answer, ""); ok != want {
			t.Errorf("code-search %q: %v (%s), want %v", answer, ok, why, want)
		}
	}
	rs := research()
	if ok, why := rs.Grade("It is policy-2026.md, not Finance Operations' 2024 rule.\nANSWER: 30 days; Data Council; 2026-03-04; corpus/policy-2026.md", ""); !ok {
		t.Errorf("research rejected a right answer that rules out the decoy: %s", why)
	}
	if ok, _ := rs.Grade("ANSWER: 30 days; Finance Operations; 2026-03-04; corpus/policy-2026.md", ""); ok {
		t.Error("research accepted the superseded decider on the ANSWER line")
	}
	co := council()
	if ok, why := co.Grade("**ANSWER: Line 17 has an Off-By-One loop; line 25 lets a NEGATIVE refund through.**", ""); !ok {
		t.Errorf("council rejected a mixed-case answer: %s", why)
	}
	hs := history()
	hws := t.TempDir()
	if err := os.MkdirAll(filepath.Join(hws, "notes"), 0o700); err != nil {
		t.Fatal(err)
	}
	for body, want := range map[string]bool{
		"Codename: Juniper\nShip date: 2026-12-05\nOwner: Dana Reyes\n":             true,
		"Codename: Juniper (was Cedar)\nShip date: 2026-12-05\nOwner: Dana Reyes\n": false, // the old codename, in the file
		"# Release\nCodename: Juniper\nShip date: 2026-12-05\nOwner: Dana Reyes\n":  false, // four lines
	} {
		if err := os.WriteFile(filepath.Join(hws, "notes", "release.md"), []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
		if ok, why := hs.Grade("ANSWER: Juniper", hws); ok != want {
			t.Errorf("history %q: %v (%s), want %v", body, ok, why, want)
		}
	}
}

func TestReportPairs(t *testing.T) {
	rep := Report{Model: "m", Results: []Result{
		{Scenario: "a", Arm: "direct", Mode: Direct, Success: true, ParentContextTokens: 0, TotalTokens: 10},
		{Scenario: "a", Arm: "subtask", Mode: Subtask, Success: true, ParentContextTokens: 5, TotalTokens: 20},
		{Scenario: "b", Arm: "direct", Mode: Direct, Success: true, ParentContextTokens: 10, TotalTokens: 10},
		{Scenario: "b", Arm: "subtask", Mode: Subtask, Success: false, Why: "failed"},
		{Scenario: "c", Arm: "direct", Mode: Direct, Success: false, Why: "failed"},
		{Scenario: "c", Arm: "subtask", Mode: Subtask, Success: true, ParentContextTokens: 5, TotalTokens: 5},
	}}
	md := Markdown(rep, true)
	if !strings.Contains(md, "- a, subtask: parent context n/a of the direct run's; total tokens 200%") || strings.Contains(md, "- b,") || strings.Contains(md, "- c,") {
		t.Fatalf("pairs:\n%s", md)
	}
}

// streamOf is a provider that sends the events given, then closes; with
// block it waits for cancellation first.
type streamOf struct {
	fakeProvider
	events []llmtypes.StreamEvent
	block  bool
}

func (p streamOf) StreamChat(ctx context.Context, _ llmtypes.ChatRequest) (<-chan llmtypes.StreamEvent, error) {
	ch := make(chan llmtypes.StreamEvent)
	go func() {
		defer close(ch)
		for _, e := range p.events {
			ch <- e
		}
		if p.block {
			<-ctx.Done()
		}
	}()
	return ch, nil
}

// TestUnfinishedStreamsKeepTheReservation: a stream cancelled after its first
// usage report, or one reporting none, is charged at least its reservation; a
// finished stream settles to what it reported.
func TestUnfinishedStreamsKeepTheReservation(t *testing.T) {
	req := llmtypes.ChatRequest{SystemPrompt: strings.Repeat("y", 3000), MaxTokens: 1000}
	start := llmtypes.StreamEvent{Type: llmtypes.EventUsage, Usage: &llmtypes.Usage{InputTokens: 10}}
	end := []llmtypes.StreamEvent{start, {Type: llmtypes.EventUsage, Usage: &llmtypes.Usage{OutputTokens: 5, StopReason: "end_turn"}}, {Type: llmtypes.EventDone}}
	for name, tc := range map[string]struct {
		p      streamOf
		cancel bool
		hold   bool
	}{
		"cancelled after message_start": {streamOf{events: []llmtypes.StreamEvent{start}, block: true}, true, true},
		"no usage":                      {streamOf{events: []llmtypes.StreamEvent{{Type: llmtypes.EventDone}}}, false, true},
		"finished":                      {streamOf{events: end}, false, false},
	} {
		m := &meter{price: Price{Input: 1, Output: 1}}
		ctx, cancel := context.WithCancel(context.Background())
		mp := &metered{Provider: tc.p, meter: m, cancel: cancel}
		ch, err := mp.StreamChat(ctx, req)
		if err != nil {
			t.Fatal(err)
		}
		<-ch
		if tc.cancel {
			cancel()
		}
		for range ch {
		}
		cancel()
		want := 15.0 / 1e6
		if tc.hold {
			want = m.worst(req)
		}
		// The settle runs as the stream's goroutine ends, just after the
		// channel closes.
		for i := 0; i < 200 && math.Abs(m.spentUSD()-want) > 1e-12; i++ {
			time.Sleep(time.Millisecond)
		}
		if got := m.spentUSD(); math.Abs(got-want) > 1e-12 {
			t.Errorf("%s: charged $%v, want $%v", name, got, want)
		}
	}
}

// TestProbeMarksRunsThatTestedNothing: a last_n arm whose subtask was given
// the facts, or chose its own context, and a result-cap arm whose result was
// never stored and fetched, are invalid.
func TestProbeMarksRunsThatTestedNothing(t *testing.T) {
	child := func(first string) llmtypes.ChatRequest {
		return llmtypes.ChatRequest{Messages: []llmtypes.ChatMessage{{Role: "user", Content: "Goal: write it\n\n" + first}}}
	}
	input := map[string]any{"goal": "g", "variant": "scribe", "context": map[string]any{"last_n": 20}}
	override := llmtypes.ChatRequest{Messages: []llmtypes.ChatMessage{{Role: "assistant", ContentBlocks: []llmtypes.ContentBlock{{Type: "tool_use", Name: "subtask", Input: &input}}}}}
	arm := Arm{Mode: Subtask, SeedLacks: []string{"Juniper"}}
	ok := Result{Mode: Subtask}
	for name, tc := range map[string]struct {
		reqs []llmtypes.ChatRequest
		arm  Arm
		r    Result
		want string
	}{
		"clean":          {[]llmtypes.ChatRequest{child("[#3 user] the owner is Dana")}, arm, ok, ""},
		"seeded":         {[]llmtypes.ChatRequest{child("[#2 user] the codename is Juniper")}, arm, ok, `already held "Juniper"`},
		"own context":    {[]llmtypes.ChatRequest{override}, arm, ok, "context.last_n"},
		"nothing stored": {nil, Arm{Mode: Subtask, NeedsStored: true}, Result{Mode: Subtask, ParentFetches: 1}, "result cap"},
	} {
		p := &probe{seedLacks: tc.arm.SeedLacks}
		for _, r := range tc.reqs {
			p.see(r)
		}
		got := invalid(Scenario{}, tc.arm, tc.r, p)
		if (tc.want == "") != (got == "") || !strings.Contains(got, tc.want) {
			t.Errorf("%s: invalid = %q, want %q", name, got, tc.want)
		}
	}
}

func TestFillCountsCompactionsAndLeavesBackgroundOut(t *testing.T) {
	recs := []agent.TraceRecord{
		{ConversationID: "root", Usage: trace.Usage{InputTokens: 100, OutputTokens: 10},
			ToolCalls:   []trace.ToolCall{{Tool: "subtask"}, {Tool: "fetch_tool_result"}},
			Compactions: []trace.Compaction{{}},
			Subtasks: []trace.Subtask{
				{ConversationID: "c1", Variant: "research", Usage: trace.Usage{InputTokens: 50}},
				{ConversationID: "c2", Variant: "worker", Background: true, Status: trace.SubtaskRunning, Usage: trace.Usage{InputTokens: 999}},
			}},
		{ConversationID: "c1", ParentConversationID: "root", Role: "research", ToolCalls: []trace.ToolCall{{Tool: "read_file"}}, Compactions: []trace.Compaction{{}, {}}},
	}
	var r Result
	r.fill(recs, "root", Price{Input: 1, Output: 1})
	if r.Compactions != 3 || r.TotalTokens != 160 || r.ParentFetches != 1 || strings.Join(r.SubtaskTools, ",") != "read_file" || strings.Join(r.Variants, ",") != "research,worker" {
		t.Fatalf("fill: %+v", r)
	}
}

func TestShorten(t *testing.T) {
	got := Shorten("auth failed: Bearer abc.def key=sk-ant-0123456789 " + strings.Repeat("x", 400))
	if strings.Contains(got, "abc.def") || strings.Contains(got, "sk-ant") || len(got) > 300 {
		t.Fatalf("Shorten = %q", got)
	}
}

func TestFind(t *testing.T) {
	if s, err := Find("council", "chore"); err != nil || len(s) != 2 || s[0].Name != "council" {
		t.Fatalf("Find = %v, %v", s, err)
	}
	if _, err := Find("nope"); err == nil {
		t.Fatal("unknown scenario found")
	}
}
